import {projectND} from './math.js';
export class WebGLAttractorRenderer{constructor(canvas){this.canvas=canvas;this.gl=canvas.getContext('webgl2',{antialias:false,alpha:false})||canvas.getContext('webgl',{antialias:false,alpha:false});if(!this.gl)throw new Error('WebGL not supported');this.resize();window.addEventListener('resize',()=>this.resize());this.program=this.createProgram(VERT,FRAG);this.buf=this.gl.createBuffer();this.rootBuf=this.gl.createBuffer()}
 shader(src,type){const gl=this.gl,sh=gl.createShader(type);gl.shaderSource(sh,src);gl.compileShader(sh);if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(sh));return sh}
 createProgram(vs,fs){const gl=this.gl,p=gl.createProgram();gl.attachShader(p,this.shader(vs,gl.VERTEX_SHADER));gl.attachShader(p,this.shader(fs,gl.FRAGMENT_SHADER));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(p));return p}
 resize(){const dpr=Math.min(2,window.devicePixelRatio||1),w=Math.floor(this.canvas.clientWidth*dpr),h=Math.floor(this.canvas.clientHeight*dpr);if(this.canvas.width!==w||this.canvas.height!==h){this.canvas.width=w;this.canvas.height=h}this.gl.viewport(0,0,w,h)}
 render(system,roots,p,camera){const gl=this.gl;this.resize();const dim=system.dim,n=system.count,data=new Float32Array(n*7);for(let i=0;i<n;i++){const off=i*dim,v=[];for(let d=0;d<dim;d++)v.push(system.pos[off+d]);const [x,y,z]=projectND(v,dim,camera.yaw,camera.pitch,camera.roll,p.zoom);const speed=Math.hypot(system.vel[off],system.vel[off+1]||0,system.vel[off+2]||0);data[i*7]=x;data[i*7+1]=y;data[i*7+2]=z;data[i*7+3]=speed;data[i*7+4]=i/n;data[i*7+5]=v[0]||0;data[i*7+6]=v[1]||0}gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE);gl.clearColor(.005,.006,.014,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(this.program);gl.bindBuffer(gl.ARRAY_BUFFER,this.buf);gl.bufferData(gl.ARRAY_BUFFER,data,gl.DYNAMIC_DRAW);const stride=28,locPos=gl.getAttribLocation(this.program,'aPos'),locMeta=gl.getAttribLocation(this.program,'aMeta'),locSeed=gl.getAttribLocation(this.program,'aSeed');gl.enableVertexAttribArray(locPos);gl.vertexAttribPointer(locPos,3,gl.FLOAT,false,stride,0);gl.enableVertexAttribArray(locMeta);gl.vertexAttribPointer(locMeta,2,gl.FLOAT,false,stride,12);gl.enableVertexAttribArray(locSeed);gl.vertexAttribPointer(locSeed,2,gl.FLOAT,false,stride,20);for(const [name,val] of Object.entries({uTime:system.t,uHue:p.hue,uLensMass:p.lensMass,uAmplification:p.amplification,uPointSize:p.pointSize,uPerspective:p.perspective}))gl.uniform1f(gl.getUniformLocation(this.program,name),val);gl.drawArrays(gl.POINTS,0,n);const rdata=new Float32Array(roots.length*7);roots.forEach((r,i)=>{rdata[i*7]=r[0]*p.zoom/2;rdata[i*7+1]=r[1]*p.zoom/2;rdata[i*7+2]=.2*Math.sin(system.t+i);rdata[i*7+3]=1;rdata[i*7+4]=i/roots.length;rdata[i*7+5]=r[0];rdata[i*7+6]=r[1]});gl.bindBuffer(gl.ARRAY_BUFFER,this.rootBuf);gl.bufferData(gl.ARRAY_BUFFER,rdata,gl.DYNAMIC_DRAW);gl.vertexAttribPointer(locPos,3,gl.FLOAT,false,stride,0);gl.vertexAttribPointer(locMeta,2,gl.FLOAT,false,stride,12);gl.vertexAttribPointer(locSeed,2,gl.FLOAT,false,stride,20);gl.uniform1f(gl.getUniformLocation(this.program,'uPointSize'),p.pointSize*3.2);gl.drawArrays(gl.POINTS,0,roots.length)}}
const VERT=`precision highp float;attribute vec3 aPos;attribute vec2 aMeta;attribute vec2 aSeed;uniform float uTime,uPointSize,uPerspective;varying vec2 vMeta,vSeed;varying float vDepth;void main(){vec3 p=aPos;float z=p.z+4.0;float persp=mix(1.0,1.0/max(.35,z),uPerspective);gl_Position=vec4(p.xy*persp,p.z*.08,1.0);gl_PointSize=uPointSize*(1.0+aMeta.x*10.0)*(.8+persp*1.5);vMeta=aMeta;vSeed=aSeed;vDepth=z;}`;
const FRAG=`precision highp float;uniform float uTime,uHue,uLensMass,uAmplification;varying vec2 vMeta,vSeed;varying float vDepth;vec3 hsv2rgb(vec3 c){vec3 p=abs(fract(c.xxx+vec3(0.,.666,.333))*6.-3.);return c.z*mix(vec3(1.),clamp(p-1.,0.,1.),c.y);}void main(){vec2 uv=gl_PointCoord.xy*2.-1.;float r=dot(uv,uv);if(r>1.)discard;float core=exp(-r*3.5);float ring=exp(-pow(length(uv)-.62,2.)*38.);float h=fract(uHue+vMeta.y*.7+sin(uTime*.08+vSeed.x*2.)*.12);vec3 col=hsv2rgb(vec3(h,.75+.25*sin(vSeed.y+uTime),.75+uAmplification*.15));float lens=1.+uLensMass*.08/max(.2,vDepth);gl_FragColor=vec4(col*(core+ring*.55)*lens,(core+ring)*.82);}`;
